    /// </summary>
    public static class RuneEffectApplier
    {
        // Lua 热更新模块缓存（避免每帧重复加载）
        private static LuaTable _luaMain;
        private static bool _luaLoaded;

        // RuneDatabase 缓存（由 RunePanel.Awake 设置，避免运行时通过 Addressables 加载）
        private static RuneDatabaseSO _database;
        private static bool _databaseLoaded;

        /// <summary>由 RunePanel 在初始化时设置数据库引用</summary>
        public static void SetDatabase(RuneDatabaseSO database)
        {
            _database = database;
            _databaseLoaded = true;
        }

        /// <summary>获取 RuneDatabase（优先使用缓存引用，回退到 Addressables）</summary>
        private static RuneDatabaseSO GetDatabase()
        {
            if (_databaseLoaded) return _database;
            _database = AssetLoader.TryLoadAsset<RuneDatabaseSO>("RuneData/RuneDatabase");
            _databaseLoaded = true;
            return _database;
        }

        /// <summary>将已装备符文的效果应用到玩家属性上</summary>
        public static void ApplyEquippedRunes(AttributePlayerBase attributes)
        {
            var database = GetDatabase();
            if (database == null || database.allRunes == null || database.allRunes.Count == 0)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到 RuneDatabase 或数据为空");
                return;
            }

            int[] equippedIds = RuneEquipmentSnapshot.GetAllEquippedIds();
            if (equippedIds.Length == 0)
            {
                Debug.Log("[RuneEffectApplier] 未装备任何符文");
                return;
            }

            // 加载 Lua 热更新配置（仅首次成功后缓存）
            LoadLuaConfig();

            string currentCharacterType = DetectCurrentCharacterType();

            foreach (int runeId in equippedIds)
            {
                var runeData = database.GetRuneById(runeId);
                if (runeData == null)
                {
                    Debug.LogWarning($"[RuneEffectApplier] 未在数据库中找到符文 ID: {runeId}");
                    continue;
                }

                Debug.Log($"[RuneEffectApplier] 应用符文效果: {runeData.runeName} (ID={runeId})");
                ApplyFromSO(attributes, runeData, currentCharacterType);
            }

            LogFinalAttributes(attributes);
        }

        // ────────────────────────────────────
        //  Lua 配置加载（仅加载效果映射和特殊技能逻辑）
        // ────────────────────────────────────

        private static void LoadLuaConfig()
        {
            if (_luaLoaded) return;

            try
            {
                var luaEnv = LuaEnvManager.Instance.LuaEnv;
                if (luaEnv == null)
                {
                    Debug.LogWarning("[RuneEffectApplier] LuaEnv 未初始化，效果映射将使用 C# 回退");
                    return;
                }

                var result = luaEnv.DoString("return require('Main')");
                if (result != null && result.Length > 0)
                {
                    _luaMain = result[0] as LuaTable;
                    _luaLoaded = true;
                    Debug.Log("[RuneEffectApplier] Lua 效果映射配置加载成功");
                }
            }
            catch (System.Exception e)
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 加载失败，效果映射将使用 C# 回退: {e.Message}");
            }
        }

        // ────────────────────────────────────
        //  公共 API：供 UI 查询符文数值（直接从 SO 读取）
        // ────────────────────────────────────

        /// <summary>获取符文的属性数值</summary>
        public static List<RunePower> GetEffectivePowers(int runeId)
        {
            var database = GetDatabase();
            return database?.GetRuneById(runeId)?.powers ?? new List<RunePower>();
        }

        /// <summary>获取符文的特殊技能名</summary>
        public static string GetEffectiveSpecialPowerName(int runeId)
        {
            var database = GetDatabase();
            return database?.GetRuneById(runeId)?.specialPowerName ?? string.Empty;
        }

        /// <summary>获取符文的特殊技能描述</summary>
        public static string GetEffectiveSpecialPowerDescription(int runeId)
        {
            var database = GetDatabase();
            return database?.GetRuneById(runeId)?.specialPowerDescription ?? string.Empty;
        }

        // ────────────────────────────────────
        //  效果应用：从 SO 读数值，从 Lua 读效果映射
        // ────────────────────────────────────

        private static void ApplyFromSO(AttributePlayerBase attr, RuneDataSO runeData, string currentCharType)
        {
            foreach (var power in runeData.powers)
            {
                ApplyPower(attr, power);
            }

            if (!string.IsNullOrEmpty(runeData.specialPowerDescription))
                ApplySpecialPower(attr, runeData, currentCharType);
        }

        private static void ApplyPower(AttributePlayerBase attr, RunePower power)
        {
            // 优先从 Lua 效果映射表查找方法名
            if (_luaMain != null)
            {
                var effectMap = _luaMain.Get<LuaTable>("RuneEffect");
                string methodName = effectMap?.Get<string>(power.label);

                if (!string.IsNullOrEmpty(methodName))
                {
                    var method = typeof(AttributePlayerBase).GetMethod(
                        methodName, BindingFlags.Public | BindingFlags.Instance);
                    if (method != null)
                    {
                        method.Invoke(attr, new object[] { power.value });
                        Debug.Log($"[RuneEffectApplier] Lua映射: {power.label} → {methodName}({power.value})");
                        return;
                    }
                    Debug.LogWarning($"[RuneEffectApplier] Lua 映射的方法不存在: {methodName}，回退到 C#");
                }
            }

            // C# 回退
            ApplyPowerFallback(attr, power);
        }

        private static void ApplyPowerFallback(AttributePlayerBase attr, RunePower power)
        {
            switch (power.label)
            {
                case "%基础伤害":
                    attr.AddAttackPower(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击力 +{power.value}% → {attr.GetAttackPower()}");
                    break;

                case "%暴击率":
                    attr.AddCriticalChance(power.value);
                    Debug.Log($"[RuneEffectApplier] 暴击率 +{power.value}% → {attr.GetCriticalChance() * 100:F1}%");
                    break;

                case "%防御力":
                    attr.AddDefensePower(power.value);
                    Debug.Log($"[RuneEffectApplier] 防御力 +{power.value}% → {attr.GetDefensePower()}");
                    break;

                case "%攻击速度":
                    attr.ReduceAttackInterval(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击速度 +{power.value} → {attr.GetAttackSpeed()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未识别的符文效果标签: '{power.label}'");
                    break;
            }
        }

        private static void ApplySpecialPower(AttributePlayerBase attr, RuneDataSO runeData, string currentCharacterType)
        {
            if (!string.IsNullOrEmpty(runeData.exclusiveCharacterType))
            {
                if (runeData.exclusiveCharacterType != currentCharacterType)
                {
                    Debug.Log($"[RuneEffectApplier] 跳过专属符文效果 [{runeData.specialPowerName}]："
                              + $"角色 {currentCharacterType} 与符文专属角色 {runeData.exclusiveCharacterType} 不匹配");
                    return;
                }
                Debug.Log($"[RuneEffectApplier] 专属符文效果匹配！角色 {currentCharacterType} ✅");
            }

            Debug.Log($"[RuneEffectApplier] 应用特殊技能: {runeData.specialPowerName} → {runeData.specialPowerDescription}");

            // 优先从 Lua 特殊技能表查找函数
            if (_luaMain != null)
            {
                var specialPowers = _luaMain.Get<LuaTable>("RuneSpecialPower");
                LuaFunction luaFunc = specialPowers?.Get<LuaFunction>(runeData.specialPowerName);

                if (luaFunc != null)
                {
                    luaFunc.Call(attr);
                    luaFunc.Dispose();
                    Debug.Log($"[RuneEffectApplier] Lua特殊技能: {runeData.specialPowerName} 已应用");
                    return;
                }
            }

            // C# 回退
            ApplySpecialPowerFallback(attr, runeData);
        }

        private static void ApplySpecialPowerFallback(AttributePlayerBase attr, RuneDataSO runeData)
        {
            switch (runeData.specialPowerName)
            {
                case "小法师专属：":
                    attr.AddMaxAttackCount(1);
                    attr.AddComboCount(1);
                    Debug.Log($"[RuneEffectApplier] 初始发射数量 +1 → {attr.GetMaxAttackCount()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未处理的特殊技能: '{runeData.specialPowerDescription}'");
                    break;
            }
        }

        // ────────────────────────────────────
        //  工具方法
        // ────────────────────────────────────

        private static string DetectCurrentCharacterType()
        {
            var player = Object.FindObjectOfType<PlayerController>();
            if (player == null)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到场景中的 PlayerController，无法检测角色类型");
                return string.Empty;
            }

            string typeName = player.GetCharacterName();
            if (string.IsNullOrEmpty(typeName))
                typeName = player.GetType().Name;

            // 去掉 "Root" 后缀，使 "WizardBoyRoot" → "WizardBoy"，与 RuneDataSO.exclusiveCharacterType 匹配
            if (typeName.EndsWith("Root"))
                typeName = typeName.Substring(0, typeName.Length - 4);

            Debug.Log($"[RuneEffectApplier] 检测到当前角色类型: {typeName}");
            return typeName;
        }

        private static void LogFinalAttributes(AttributePlayerBase attr)
        {
            Debug.Log($"[RuneEffectApplier] ── 符文应用后最终属性 ──\n" +
                      $"攻击力: {attr.GetAttackPower()}\n" +
                      $"防御力: {attr.GetDefensePower()}\n" +
                      $"暴击率: {attr.GetCriticalChance() * 100:F1}%\n" +
                      $"攻击间隔: {attr.GetAttackInterval()}\n" +
                      $"移动速度: {attr.GetMoveSpeed()}");
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace Controllers.Rune
{
    /// <summary>
    /// 跨场景缓存装备的符文 ID
    /// 大厅出发前由 RunePanel 捕获，游戏场景中由 RuneEffectApplier 读取。
    /// GameManager 为 DontDestroyOnLoad，因此静态数据在场景切换后仍存在。
    /// </summary>
    public static class RuneEquipmentSnapshot
    {
        public static int EquippedRuneId1 { get; private set; } = -1;
        public static int EquippedRuneId2 { get; private set; } = -1;

        /// <summary>从 RunePanel 捕获当前装备的符文 ID</summary>
        public static void CaptureFrom(RunePanel panel)
        {
            EquippedRuneId1 = panel.GetEquip1()?.EquippedRuneId ?? -1;
            EquippedRuneId2 = panel.GetEquip2()?.EquippedRuneId ?? -1;
            Debug.Log($"[RuneEquipmentSnapshot] 捕获装备数据: Slot1={EquippedRuneId1}, Slot2={EquippedRuneId2}");
        }

        /// <summary>获取所有已装备的符文 ID（过滤掉未装备的 -1）</summary>
        public static int[] GetAllEquippedIds()
        {
            var ids = new List<int>(2);
            if (EquippedRuneId1 != -1) ids.Add(EquippedRuneId1);
            if (EquippedRuneId2 != -1) ids.Add(EquippedRuneId2);
            return ids.ToArray();
        }

        public static void SetBoth(int runeId1, int runeId2)
        {
            EquippedRuneId1 = runeId1;
            EquippedRuneId2 = runeId2;
        }
    }
}

using System.Collections;
using Controllers.Item;
using UnityEngine;

namespace Controllers.Rune
{
    /// <summary>
    /// 符文掉落物 — 从敌人身上掉落，以抛物线轨迹飞出去然后落地
    /// 玩家靠近拾取后，符文效果即时应用到玩家属性
    /// </summary>
    public class DropItemRune : DropItemBase
    {
        [Header("符文数据")]
        [SerializeField] private RuneDataSO runeData;

        [Header("抛物线参数")]
        [SerializeField] private float launchAngleMin = 50f;       // 最小发射仰角（度）
        [SerializeField] private float launchAngleMax = 70f;       // 最大发射仰角（度）
        [SerializeField] private float launchSpeed = 6f;           // 发射初速度
        [SerializeField] private float launchRandomRadius = 3f;    // 落点随机散布半径
        [SerializeField] private float spinTorque = 3f;            // 飞行中的自旋扭矩

        [Header("落地检测")]
        [SerializeField] private float landVelocityThreshold = 0.2f; // 判定落地的速度阈值
        [SerializeField] private float groundCheckDistance = 2f;     // 向下检测地面的距离
        [SerializeField] private LayerMask groundLayer = -1;         // 地面层（-1 = Everything）
        [SerializeField] private float groundYOffset = 0.05f;        // 落地后离地高度

        [Header("生命周期")]
        [SerializeField] private float maxLifetime = 30f;           // 无人拾取时自动消失的时间


        [Header("子类特效")]
        [SerializeField] private GameObject trail;
        [SerializeField] private GameObject realyFx;
        // ── 运行时状态 ──
        private bool hasLanded = false;
        private float launchTime;               // 发射时刻（防 OnCollisionEnter 误触）
        private Coroutine landCheckCoroutine;
        private Coroutine lifetimeCoroutine;

        // ======================================================================
        //  Setup — 由敌人掉落时调用，传入掉落的符文数据
        // ======================================================================

        /// <summary>设置该掉落物对应的符文数据</summary>
        public void Setup(RuneDataSO data)
        {
            runeData = data;
        }

        /// <summary>获取该掉落物携带的符文数据</summary>
        public RuneDataSO GetRuneData() => runeData;

        // ======================================================================
        //  生命周期（继承自 DropItemBase）
        // ======================================================================

        /// <summary>
        /// GameObject 被激活时调用：
        /// 基类 OnEnable() 会重置飞行状态并调用 ApplyExplosionEffect()
        /// 我们 override ApplyExplosionEffect() 来实现抛物线
        /// </summary>
        protected override void OnEnable()
        {
            hasLanded = false;

            // 清除之前的协程
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }

            base.OnEnable();
        }

        protected override void OnDisable()
        {
            base.OnDisable();

            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }

        // ======================================================================
        //  抛物线弹射（override 基类的简单爆炸）
        // ======================================================================

        /// <summary>
        /// 重写基类的 ApplyExplosionEffect：
        /// 以高抛角度将符文弹射出去，形成抛物线轨迹
        /// </summary>
        protected override void ApplyExplosionEffect()
        {
            if (Rb == null)
                return;

            // 1. 重置物理状态
            Rb.velocity = Vector3.zero;
            Rb.angularVelocity = Vector3.zero;
            Rb.isKinematic = false;
            Rb.useGravity = true;

            // 记录发射时刻，防止 OnCollisionEnter 误触
            launchTime = UnityEngine.Time.time;

            // 2. 随机偏移落点方向（在敌人周围散布）
            Vector2 randomCircle = Random.insideUnitCircle.normalized;
            Vector3 horizontalDir = new Vector3(randomCircle.x, 0, randomCircle.y);

            // 3. 计算发射速度
            //    已知水平距离 distance，仰角 angle，初速度 launchSpeed
            //    水平分量: v_x = launchSpeed * cos(angle)
            //    垂直分量: v_y = launchSpeed * sin(angle)
            float angle = Random.Range(launchAngleMin, launchAngleMax);
            float angleRad = angle * Mathf.Deg2Rad;

            Vector3 launchVelocity = horizontalDir * launchSpeed * Mathf.Cos(angleRad)
                                   + Vector3.up * launchSpeed * Mathf.Sin(angleRad);

            // 4. 施加瞬时速度
            Rb.AddForce(launchVelocity, ForceMode.VelocityChange);

            // 5. 添加旋转（让符文在空中翻转）
            Rb.AddTorque(new Vector3(
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f)
            ) * spinTorque, ForceMode.VelocityChange);

            // 5.5 增加阻力，防止落地后滑行
            Rb.drag = 2f;
            Rb.angularDrag = 2f;

            // 6. 启动落地检测协程
            landCheckCoroutine = StartCoroutine(CheckLanding());

            // 7. 启动生命周期计时（超时自动消失）
            lifetimeCoroutine = StartCoroutine(AutoDespawnAfterDelay());
        }

        // ======================================================================
        //  落地检测
        // ======================================================================

        private IEnumerator CheckLanding()
        {
            // 给一个最小飞行时间，避免刚发射就被判定落地
            float minFlightTime = 0.4f;
            float timer = 0f;

            while (!hasLanded)
            {
                timer += UnityEngine.Time.deltaTime;

                // 条件 A：至少飞了 minFlightTime
                // 条件 B：速度很低
                // 条件 C：在地面附近（Raycast 检测）
                if (timer > minFlightTime && Rb.velocity.magnitude < landVelocityThreshold)
                {
                    // 向下发射射线检测地面
                    if (Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit,
                            groundCheckDistance, groundLayer))
                    {
                        // 停在落地点正上方
                        transform.position = new Vector3(
                            transform.position.x,
                            hit.point.y + groundYOffset,
                            transform.position.z
                        );

                        OnLand();
                        yield break;
                    }
                    else
                    {
                        // 速度很低但不在"地面"上 — 可能卡在半空
                        // 再等一小段时间强制落地
                        yield return new WaitForSeconds(0.5f);

                        if (!hasLanded)
                        {
                            // 强制落地：使用当前位置的 Y 作为地面
                            OnLand();
                            yield break;
                        }
                    }
                }

                yield return null; // 每帧检测
            }
        }

        private void OnLand()
        {
            hasLanded = true;
            Debug.Log($"[DropItemRune] 符文落地: {runeData?.runeName ?? "未知符文"}");

            // 冻结物理，符文稳稳停住
            if (Rb != null)
            {
                Rb.velocity = Vector3.zero;
                Rb.angularVelocity = Vector3.zero;
                Rb.isKinematic = true;
                Rb.useGravity = false;
            }

            // 将 transform 摆正（防止歪着插地上）
            transform.rotation = Quaternion.identity;

            // 关闭拖尾特效
            if (trail != null)
                trail.SetActive(false);
            if (realyFx != null)
                realyFx.SetActive(true);
        }

        // ======================================================================
        //  物理碰撞落地（比协程的速度检测更可靠）
        // ======================================================================

        private void OnCollisionEnter(Collision collision)
        {
            if (hasLanded) return;

            // 最小飞行时间保护，防止刚生成就误触落地
            if (UnityEngine.Time.time - launchTime < 0.5f) return;

            // 检查碰撞的物体是否属于 groundLayer
            int layerMask = 1 << collision.gameObject.layer;
            if ((groundLayer.value & layerMask) != 0)
            {
                OnLand();
            }
        }

        // ======================================================================
        //  超时自动消失
        // ======================================================================

        private IEnumerator AutoDespawnAfterDelay()
        {
            yield return new WaitForSeconds(maxLifetime);

            // 如果还没被捡走，超时自动销毁
            if (!DropItemData.isFlyingToPlayer && hasLanded)
            {
                Debug.Log($"[DropItemRune] 符文超时消失: {runeData?.runeName ?? "未知"}");
                DespawnSelf();
            }
        }

        // ======================================================================
        //  拾取到达（override 基类）
        // ======================================================================

        /// <summary>
        /// 符文飞到玩家身边后调用 — 存入局外背包并销毁
        /// </summary>
        protected override void OnReachPlayer()
        {
            if (runeData != null)
            {
                Debug.Log($"[DropItemRune] 玩家拾取符文: {runeData.runeName} (ID={runeData.runeId})");

                // 存入局外背包（不应用局内效果）
                RuneInventory.AddRune(runeData.runeId);
            }

            DespawnSelf();
        }

        // ======================================================================
        //  回收（本地直接销毁）
        // ======================================================================

        private void DespawnSelf()
        {
            Destroy(gameObject);
        }

        // ======================================================================
        //  OnDestroy 清理协程（防止销毁后协程还在跑）
        // ======================================================================

        private void OnDestroy()
        {
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using Controllers.Rune;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UI.Framework.Base;

namespace UI.Framework
{
    public class RuneSlot : UIWidget, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler,
                             IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        [Header("RuneSlot UI")]
        [SerializeField] private Image iconImage;
        [SerializeField] private Text nameText;

        [Header("RuneSlot Data")]
        [SerializeField] private int slotId;

        [Header("选中高亮")]
        [SerializeField] private Image bgcImage; // BGC 子对象的 Image（拖拽赋值）
        [SerializeField] private Sprite selectedSprite;   // 选中时的 BGC 图片
        [SerializeField] private Sprite deselectedSprite; // 未选中时的 BGC 图片
        [SerializeField] private Sprite hoverSprite;      // 悬浮时的 BGC 图片

        [Header("已装备标记")]
        [SerializeField] private GameObject equippedMarkObject; // 已装备标记（含子对象 TextMeshProUGUI，拖拽赋值）

        [Header("拖拽")]
        [SerializeField][Range(0f, 1f)] private float dragGhostAlpha = 0.6f; // 拖拽虚影透明度

        /// <summary>点击事件，供 RunePanel 订阅</summary>
        public event Action<RuneSlot> OnClicked;

        /// <summary>开始拖拽符文时触发，供 RunePanel 订阅</summary>
        public static event Action<RuneSlot> OnDragStarted;

        /// <summary>拖拽结束时触发（无论是否落在有效区域），供 RunePanel 订阅</summary>
        public static event Action<RuneSlot> OnDragEnded;

        // 通过 Setup() 注入的符文数据资产
        private RuneDataSO runeData;

        // 拖拽状态
        private Image dragGhostImage;
        private RectTransform dragGhostRect;
        private Canvas dragCanvas;

        // ── 只读公开属性 ──

        public int SlotId => slotId;
        public RuneDataSO RuneData => runeData;

        /// <summary>获取热更新后的有效数值（优先 Lua，回退 SO 默认值）</summary>
        public List<RunePower> RunePowers
        {
            get
            {
                if (runeData != null)
                    return RuneEffectApplier.GetEffectivePowers(runeData.runeId);
                return new List<RunePower>();
            }
        }

        public string RuneName => runeData != null ? runeData.runeName : string.Empty;
        public string SpecialPowerName => runeData != null
            ? RuneEffectApplier.GetEffectiveSpecialPowerName(runeData.runeId) : string.Empty;
        public string SpecialPowerDescription => runeData != null
            ? RuneEffectApplier.GetEffectiveSpecialPowerDescription(runeData.runeId) : string.Empty;

        // ── 外部注入 ──

        /// <summary>用 RuneDataSO 设置该槽位的符文数据</summary>
        public void Setup(RuneDataSO data)
        {
            runeData = data;

            if (data == null)
            {
                if (iconImage != null) iconImage.sprite = null;
                if (nameText != null) nameText.text = string.Empty;
                return;
            }

            slotId = data.runeId;

            if (iconImage != null)
                iconImage.sprite = data.icon;

            if (nameText != null)
                nameText.text = data.runeName;
        }

        /// <summary>设置已装备标记的显示状态</summary>
        public void SetEquipped(bool equipped)
        {
            if (equippedMarkObject != null)
                equippedMarkObject.SetActive(equipped);
        }

        // ── UIWidget 生命周期 ──

        protected override void AutoBindComponents()
        {
            // 自动查找 Icon 子对象
            if (iconImage == null)
            {
                var iconTr = transform.Find("Icon");
                if (iconTr != null)
                    iconImage = iconTr.GetComponent<Image>();
            }

            // 自动查找 Name 子对象
            if (nameText == null)
            {
                var nameTr = transform.Find("Name");
                if (nameTr != null)
                    nameText = nameTr.GetComponent<Text>();
            }

            // 确保自身 Image 可接收射线，避免 prefab 根节点没有 Image 时无法触发点击
            var image = GetComponent<Image>();
            if (image == null)
            {
                image = gameObject.AddComponent<Image>();
                image.color = Color.clear;
            }
            image.raycastTarget = true;

            // 初始状态设为未选中图片
            if (bgcImage != null && deselectedSprite != null)
                bgcImage.sprite = deselectedSprite;

            // 已装备标记初始为不激活（由 SetEquipped 控制）
            if (equippedMarkObject != null)
                equippedMarkObject.SetActive(false);
        }

        // ──────────────────────────────────────────────
        //  选中 / 取消选中 → 切换 BGC 图片
        // ──────────────────────────────────────────────

        protected override void OnSelectCompleted()
        {
            if (bgcImage != null && selectedSprite != null)
                bgcImage.sprite = selectedSprite;
        }

        protected override void OnDeselectCompleted()
        {
            if (bgcImage != null && deselectedSprite != null)
                bgcImage.sprite = deselectedSprite;
        }

        // ── 指针事件（点击 + 悬浮） ──

        public void OnPointerClick(PointerEventData eventData)
        {
            OnClicked?.Invoke(this);
        }

        public void OnPointerEnter(PointerEventData eventData)
        {
            PlayHoverEnter();

            // 未选中时切换为悬浮图片
            if (!IsSelected && bgcImage != null && hoverSprite != null)
                bgcImage.sprite = hoverSprite;
        }

        public void OnPointerExit(PointerEventData eventData)
        {
            PlayHoverExit();

            // 恢复为对应状态的图片
            if (bgcImage == null) return;
            bgcImage.sprite = IsSelected ? selectedSprite : deselectedSprite;
        }

        // ── 拖拽（IBeginDragHandler / IDragHandler / IEndDragHandler） ──

        public void OnBeginDrag(PointerEventData eventData)
        {
            // 没有数据的符文不允许拖拽
            if (runeData == null || iconImage == null || iconImage.sprite == null)
                return;

            // 查找根 Canvas
            if (dragCanvas == null)
                dragCanvas = GetComponentInParent<Canvas>();
            if (dragCanvas == null) return;

            // 创建虚影 GameObject
            var ghostGO = new GameObject($"{name}_DragGhost", typeof(Image));
            ghostGO.transform.SetParent(dragCanvas.transform, false);
            ghostGO.transform.SetAsLastSibling();

            dragGhostImage = ghostGO.GetComponent<Image>();
            dragGhostImage.sprite = iconImage.sprite;
            dragGhostImage.raycastTarget = false;
            dragGhostImage.color = new Color(1f, 1f, 1f, dragGhostAlpha);

            dragGhostRect = ghostGO.GetComponent<RectTransform>();
            // 保持与原始图标一致的尺寸和比例
            dragGhostRect.sizeDelta = iconImage.rectTransform.sizeDelta;
            dragGhostRect.pivot = iconImage.rectTransform.pivot;

            // 初始位置对齐鼠标
            UpdateGhostPosition(eventData);

            // 通知 RunePanel 拖拽开始
            OnDragStarted?.Invoke(this);
        }

        public void OnDrag(PointerEventData eventData)
        {
            if (dragGhostRect == null || dragCanvas == null) return;
            UpdateGhostPosition(eventData);
        }

        public void OnEndDrag(PointerEventData eventData)
        {
            // 销毁虚影
            if (dragGhostImage != null)
            {
                Destroy(dragGhostImage.gameObject);
                dragGhostImage = null;
                dragGhostRect = null;
            }

            // 通知拖拽结束
            OnDragEnded?.Invoke(this);
        }

        /// <summary>将虚影移动到当前鼠标位置</summary>
        private void UpdateGhostPosition(PointerEventData eventData)
        {
            if (dragGhostRect == null || dragCanvas == null) return;

            RectTransformUtility.ScreenPointToLocalPointInRectangle(
                dragCanvas.transform as RectTransform,
                eventData.position,
                eventData.pressEventCamera,
                out var localPos
            );
            dragGhostRect.localPosition = localPos;
        }
    }
}

using System;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UI.Framework.Base;
using UI.Framework;

/// <summary>
/// 符文装备插槽（RuneEquip_1 / RuneEquip_2）
/// 可选中、可显示已装备的符文图标
/// </summary>
public class RuneEquip : UIWidget, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler,
                             IDropHandler
{
    [Header("RuneEquip")]
    [SerializeField] private int equipIndex; // 0 = 插槽1, 1 = 插槽2
    [SerializeField] private Image iconImage; // 显示符文图标的子对象
    [SerializeField] private Image highlightImage; // 拖拽高亮用的 Image（拖拽赋值）
    [SerializeField] private Color normalColor = Color.white; // 未高亮时的颜色

    public int EquipIndex => equipIndex;
    public int EquippedRuneId { get; private set; } = -1;
    public Sprite EquippedIcon { get; private set; }
    public bool HasRune => EquippedRuneId != -1;

    /// <summary>已装备的具体 RuneSlot 实例（用于精确匹配标记）</summary>
    public RuneSlot EquippedRuneSlot { get; private set; }

    /// <summary>选中事件，供 RunePanel 订阅</summary>
    public event Action<RuneEquip> OnSelected;

    /// <summary>拖拽丢落事件，供 RunePanel 订阅</summary>
    public event Action<RuneEquip, RuneSlot> OnDropReceived;

    // ──────────────────────────────────────────────
    //  装备 / 卸下
    // ──────────────────────────────────────────────

    /// <summary>装备符文到该插槽</summary>
    public void Equip(int runeId, Sprite icon, RuneSlot runeSlot)
    {
        EquippedRuneId = runeId;
        EquippedIcon = icon;
        EquippedRuneSlot = runeSlot;

        if (iconImage != null)
            iconImage.sprite = icon;
    }

    /// <summary>卸下当前符文</summary>
    public void Unequip()
    {
        EquippedRuneId = -1;
        EquippedIcon = null;
        EquippedRuneSlot = null;

        if (iconImage != null)
            iconImage.sprite = null;
    }

    // ──────────────────────────────────────────────
    //  选中 / 取消选中
    // ──────────────────────────────────────────────

    /// <summary>设置该插槽的选中状态</summary>
    public void SetSelected(bool selected)
    {
        if (selected)
            PlaySelect();
        else
            PlayDeselect();
    }

    // ──────────────────────────────────────────────
    //  UIWidget
    // ──────────────────────────────────────────────

    protected override void AutoBindComponents()
    {
        // 自动查找 Icon 子对象
        if (iconImage == null)
        {
            var iconTr = transform.Find("Icon");
            if (iconTr != null)
                iconImage = iconTr.GetComponent<Image>();
        }

        // 确保自身 Image 可接收射线
        var img = GetComponent<Image>();
        if (img != null)
            img.raycastTarget = true;
    }

    // ──────────────────────────────────────────────
    //  点击 → 选中该插槽
    // ──────────────────────────────────────────────

    public void OnPointerClick(PointerEventData eventData)
    {
        OnSelected?.Invoke(this);
    }

    public void OnPointerEnter(PointerEventData eventData)
    {
        PlayHoverEnter();
    }

    public void OnPointerExit(PointerEventData eventData)
    {
        PlayHoverExit();
    }

    // ──────────────────────────────────────────────
    //  拖拽丢落（IDropHandler）
    // ──────────────────────────────────────────────

    public void OnDrop(PointerEventData eventData)
    {
        if (eventData.pointerDrag == null) return;

        var runeSlot = eventData.pointerDrag.GetComponent<RuneSlot>();
        if (runeSlot != null && runeSlot.RuneData != null)
            OnDropReceived?.Invoke(this, runeSlot);
    }

    /// <summary>
    /// 设置拖拽目标高亮状态（由 RunePanel 在拖拽开始/结束时调用）
    /// </summary>
    public void SetHighlight(bool highlight, Color highlightColor)
    {
        if (highlightImage == null) return;
        highlightImage.color = highlight ? highlightColor : normalColor;
    }
}

using System;
using System.Collections.Generic;
using Core;
using Core.Channels.General;
using Controllers.Rune;
using Managers;
using UI.Framework;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;
using UnityEngine.UI;

public class RunePanel : UIScreen
{
  [Header("Rune Panel Buttons")]
  [SerializeField] private Button equipButton;
  [SerializeField] private Button breakdownButton;

  [Header("符文列表（动态生成）")]
  [SerializeField] private GameObject runeSlotPrefab;       // 符文插槽预制体
  [SerializeField] private GameObject runeSlotListPanel;    // 符文列表父级 Panel（生成的预制体挂在此 Panel 下）
  [SerializeField] private RuneDatabaseSO runeDatabase;    // 符文数据库（直接引用，与 ShopPanel 一致）

  [Header("装备插槽")]
  [SerializeField] private RuneEquip runeEquip1;
  [SerializeField] private RuneEquip runeEquip2;

  [Header("拖拽")]
  [SerializeField] private Color dragTargetHighlightColor = new Color(1f, 0.92f, 0.46f, 1f); // 拖拽时装备插槽高亮色

  // 运行时动态生成的符文插槽列表
  private List<GameObject> runeSlotList = new List<GameObject>();

  // 选中状态
  private GameObject selectedRuneListItem;
  private RuneEquip selectedEquip; // 当前选中的装备插槽

  // ── 玩家拥有的符文（后续从存档加载） ──
  private List<int> ownedRuneIds = new List<int>();

  // 默认初始符文
  private static List<int> DefaultRuneIds = new List<int> { 0, 0, 1, 1, 1 };

  /// <summary>玩家已拥有的符文 ID 列表</summary>
  public IReadOnlyList<int> OwnedRuneIds => ownedRuneIds;

  // --- 事件：通知 LobbyCanvas 更新图标视觉 ---
  /// <summary>符文装备事件 (slotIndex, equippedSprite)</summary>
  public event Action<int, Sprite> OnRuneEquipped;
  /// <summary>符文卸下事件 (slotIndex)</summary>
  public event Action<int> OnRuneUnequipped;
  /// <summary>符文列表项选中事件</summary>
  public event Action<RuneSlot> OnRuneItemSelected;

  // ──────────────────────────────────────────────
  //  UIScreen 生命周期
  // ──────────────────────────────────────────────

  protected override void Awake()
  {
    screenId = "RunePanel";
    base.Awake();
    UIManager.Instance.RegisterScreen(this);
    Initialize();
  }

  private void Initialize()
  {
    // 将 RuneDatabase 引用注入 RuneEffectApplier（供游戏场景中使用）
    if (runeDatabase != null)
      RuneEffectApplier.SetDatabase(runeDatabase);

    // 初始化已拥有符文（默认符文 + RuneInventory 中已购买的符文）
    ownedRuneIds = new List<int>(DefaultRuneIds);
    MergeInventoryRunes();

    // 绑定装备按钮
    if (equipButton != null)
      equipButton.onClick.AddListener(OnEquipClicked);

    // 绑定分解按钮
    if (breakdownButton != null)
      breakdownButton.onClick.AddListener(OnBreakdownClicked);

    // 动态生成符文列表（根据 ownedRuneIds 过滤 RuneDatabase）
    BuildRuneSlotList();

    // 默认装备：RuneEquip_1 ← RuneSlot[0], RuneEquip_2 ← RuneSlot[1]
    EquipDefaultRunes();

    // 刷新已装备标记 + 已装备符文排到最前面
    RefreshAllEquippedMarks();
    ReorderEquippedToFront();

    // 订阅装备插槽选中事件，默认选中插槽1
    if (runeEquip1 != null)
    {
      runeEquip1.OnSelected += OnEquipSlotSelected;
      runeEquip1.OnDropReceived += OnRuneDropReceived;      // 拖拽丢落
      selectedEquip = runeEquip1;
      runeEquip1.SetSelected(true);
    }
    if (runeEquip2 != null)
    {
      runeEquip2.OnSelected += OnEquipSlotSelected;
      runeEquip2.OnDropReceived += OnRuneDropReceived;      // 拖拽丢落
    }

    // 订阅符文拖拽事件（全局，用于高亮可拖放区域）
    RuneSlot.OnDragStarted += OnAnyRuneDragStarted;
    RuneSlot.OnDragEnded += OnAnyRuneDragEnded;
  }

  protected override void OnBeforeOpen()
  {
    base.OnBeforeOpen();

    // 检查是否有新购买的符文，如有则重建列表
    // 或首次加载失败（Addressables 未就绪）时重试
    if (MergeInventoryRunes() || runeSlotList.Count == 0)
    {
      BuildRuneSlotList();
      RestoreEquipReferences();
    }

    // 刷新已装备标记 + 已装备符文排到最前面
    RefreshAllEquippedMarks();
    ReorderEquippedToFront();

    // 取消旧的选中，重新选中列表第 1 项
    DeselectAllItems();
    if (runeSlotList.Count > 0)
      SetRuneSlotItemSelected(runeSlotList[0]);

    // 默认选中装备槽 1
    if (selectedEquip != runeEquip1)
    {
      selectedEquip?.SetSelected(false);
      selectedEquip = runeEquip1;
    }
    if (runeEquip1 != null)
      runeEquip1.SetSelected(true);
  }

  protected override void OnAfterClose()
  {
    base.OnAfterClose();
    DeselectAllItems();
  }

  // ──────────────────────────────────────────────
  //  RuneInventory 同步
  // ──────────────────────────────────────────────

  /// <summary>
  /// 从默认符文 + RuneInventory 已购买符文重建 ownedRuneIds。
  /// 返回 true 表示列表有变化（有新购买的符文）。
  /// </summary>
  private bool MergeInventoryRunes()
  {
    var newIds = new List<int>(DefaultRuneIds);
    newIds.AddRange(RuneInventory.GetAllRuneIds());

    if (newIds.Count == ownedRuneIds.Count)
    {
      bool same = true;
      for (int i = 0; i < newIds.Count; i++)
      {
        if (newIds[i] != ownedRuneIds[i]) { same = false; break; }
      }
      if (same) return false;
    }

    ownedRuneIds = newIds;
    Debug.Log($"[RunePanel] 符文列表更新：共 {ownedRuneIds.Count} 个（默认 {DefaultRuneIds.Count} + 购买 {newIds.Count - DefaultRuneIds.Count}）");
    return true;
  }

  /// <summary>
  /// 重建列表后，重新关联 RuneEquip 的 RuneSlot 引用
  /// （旧引用已随列表销毁，需要指向新的 RuneSlot 实例）
  /// </summary>
  private void RestoreEquipReferences()
  {
    // 标记是否已重新关联了每个装备插槽
    bool equip1Linked = false, equip2Linked = false;

    foreach (var go in runeSlotList)
    {
      if (go == null) continue;
      var slot = go.GetComponent<RuneSlot>();
      if (slot == null || slot.RuneData == null) continue;

      int runeId = slot.RuneData.runeId;

      if (!equip1Linked && runeEquip1 != null && runeEquip1.EquippedRuneId == runeId)
      {
        runeEquip1.Equip(runeId, slot.RuneData.icon, slot);
        equip1Linked = true;
      }
      else if (!equip2Linked && runeEquip2 != null && runeEquip2.EquippedRuneId == runeId)
      {
        runeEquip2.Equip(runeId, slot.RuneData.icon, slot);
        equip2Linked = true;
      }
    }
  }

  // ──────────────────────────────────────────────
  //  动态生成符文插槽
  // ──────────────────────────────────────────────

  private void BuildRuneSlotList()
  {
    // 清空上一次生成的列表
    foreach (var go in runeSlotList)
      Destroy(go);
    runeSlotList.Clear();

    if (runeSlotPrefab == null)
    {
      Debug.LogError("[RunePanel] runeSlotPrefab 未赋值，无法动态生成符文列表");
      return;
    }

    if (runeSlotListPanel == null)
    {
      Debug.LogError("[RunePanel] runeSlotListPanel 未赋值，无法动态生成符文列表");
      return;
    }

    // 使用直接引用的符文数据库（与 ShopPanel 方式一致）
    if (runeDatabase == null || runeDatabase.allRunes.Count == 0)
    {
      Debug.LogWarning("[RunePanel] runeDatabase 未赋值或数据为空");
      return;
    }

    // 构建 runeId → RuneDataSO 字典
    var runeDataMap = new Dictionary<int, RuneDataSO>();
    foreach (var data in runeDatabase.allRunes)
      if (data != null && !runeDataMap.ContainsKey(data.runeId))
        runeDataMap[data.runeId] = data;

    // 对 ownedRuneIds 排序（自动按 runeId 升序排列）
    ownedRuneIds.Sort();

    // 每个 ID 生成一个插槽（支持重复符文）
    for (int i = 0; i < ownedRuneIds.Count; i++)
    {
      int runeId = ownedRuneIds[i];

      if (!runeDataMap.TryGetValue(runeId, out var runeData))
      {
        Debug.LogWarning($"[RunePanel] ownedRuneIds 包含未在数据库中注册的 ID: {runeId}");
        continue;
      }

      // 实例化预制体
      var go = Instantiate(runeSlotPrefab, runeSlotListPanel.transform);
      go.name = $"RuneSlot_{runeId}_{runeData.runeName}_{i:D2}";

      // 设置符文数据
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot != null)
      {
        runeSlot.Setup(runeData);
        runeSlot.OnClicked += OnRuneSlotClicked;

        // 标记已装备状态
        bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneId == runeId) ||
                          (runeEquip2 != null && runeEquip2.EquippedRuneId == runeId);
        runeSlot.SetEquipped(isEquipped);
      }

      runeSlotList.Add(go);
    }
  }

  private void OnRuneSlotClicked(RuneSlot runeSlot)
  {
    if (runeSlot == null || runeSlot.gameObject == selectedRuneListItem)
      return;

    SetRuneSlotItemSelected(runeSlot.gameObject);
  }

  /// <summary>
  /// 默认装备：取前两个不同种类的符文分别装备到两个插槽
  /// </summary>
  private void EquipDefaultRunes()
  {
    var usedRuneIds = new HashSet<int>();
    int equipIndex = 0;
    RuneEquip[] equipSlots = { runeEquip1, runeEquip2 };

    for (int i = 0; i < runeSlotList.Count && equipIndex < 2; i++)
    {
      var slot = runeSlotList[i].GetComponent<RuneSlot>();
      if (slot == null || slot.RuneData == null)
        continue;

      int runeId = slot.RuneData.runeId;

      // 跳过已装备过的符文种类
      if (usedRuneIds.Contains(runeId))
        continue;

      usedRuneIds.Add(runeId);
      var equip = equipSlots[equipIndex];
      if (equip != null)
      {
        equip.Equip(runeId, slot.RuneData.icon, slot);
        equipIndex++;
      }
    }

    if (equipIndex == 0)
      Debug.LogWarning("[RunePanel] 没有可装备的默认符文");
  }

  private void SetRuneSlotItemSelected(GameObject item)
  {
    // 取消选中之前的项
    if (selectedRuneListItem != null && selectedRuneListItem != item)
    {
      var prevSlot = selectedRuneListItem.GetComponent<RuneSlot>();
      prevSlot?.PlayDeselect();
    }

    selectedRuneListItem = item;

    // 选中新项 + 显示详情
    var runeSlot = item?.GetComponent<RuneSlot>();
    if (runeSlot != null)
    {
      runeSlot.PlaySelect();

      var args = new RuneEquipArgs(
          runeSlot.SlotId,
          runeSlot.RuneName,
          runeSlot.RunePowers,
          runeSlot.SpecialPowerName,
          runeSlot.SpecialPowerDescription
      );
      EventChannelLocator.MainContainer.runeInfoChannel.Raise(args);

      OnRuneItemSelected?.Invoke(runeSlot);
    }
  }

  // ──────────────────────────────────────────────
  //  装备插槽选择
  // ──────────────────────────────────────────────

  private void OnEquipSlotSelected(RuneEquip equip)
  {
    if (equip == null || equip == selectedEquip)
      return;

    // 取消选中旧插槽
    selectedEquip?.SetSelected(false);

    // 选中新插槽
    selectedEquip = equip;
    selectedEquip.SetSelected(true);
  }

  // ──────────────────────────────────────────────
  //  装备符文
  // ──────────────────────────────────────────────

  private void OnEquipClicked()
  {
    if (selectedRuneListItem == null)
    {
      Debug.LogWarning("[RunePanel] 没有选中的符文图标");
      return;
    }

    var runeSlot = selectedRuneListItem.GetComponent<RuneSlot>();
    if (runeSlot == null)
    {
      Debug.LogWarning("[RunePanel] 选中的符文图标没有 RuneSlot 组件");
      return;
    }

    if (selectedEquip == null)
    {
      Debug.LogWarning("[RunePanel] 没有选中的装备插槽");
      return;
    }

    if (EquipRune(runeSlot, selectedEquip))
    {
      // 装备成功 → 刷新标记并重排
      RefreshAllEquippedMarks();
      ReorderEquippedToFront();
    }
  }

  /// <summary>
  /// 执行装备 / 调换逻辑，供点击装备按钮和拖拽丢落共用
  /// </summary>
  /// <returns>true = 装备成功 / 调换成功</returns>
  public bool EquipRune(RuneSlot runeSlot, RuneEquip equipSlot)
  {
    if (runeSlot == null || equipSlot == null)
    {
      Debug.LogWarning("[RunePanel] EquipRune 参数为空");
      return false;
    }

    if (runeSlot.RuneData == null)
    {
      Debug.LogWarning("[RunePanel] 符文数据为空，无法装备");
      return false;
    }

    int newRuneId = runeSlot.RuneData.runeId;

    // 情况1：该符文已装备在当前插槽 → 无效果
    if (equipSlot.EquippedRuneId == newRuneId)
    {
      Debug.Log("[RunePanel] 该符文已装备在选中插槽，无变化");
      return false;
    }

    if (runeSlot.RuneData.icon == null)
    {
      Debug.LogWarning("[RunePanel] 符文没有图标数据");
      return false;
    }

    Sprite newIcon = runeSlot.RuneData.icon;
    RuneEquip otherEquip = (equipSlot == runeEquip1) ? runeEquip2 : runeEquip1;

    // 情况2：该符文已装备在另一个插槽 → 调换两插槽的符文
    if (otherEquip != null && otherEquip.EquippedRuneId == newRuneId)
    {
      int swappedRuneId = equipSlot.EquippedRuneId;
      Sprite swappedIcon = equipSlot.EquippedIcon;
      RuneSlot swappedSlot = equipSlot.EquippedRuneSlot;

      // 选中插槽 ← 新符文
      equipSlot.Equip(newRuneId, newIcon, runeSlot);

      if (swappedRuneId != -1)
      {
        // 另一插槽 ← 旧符文（调换）
        otherEquip.Equip(swappedRuneId, swappedIcon, swappedSlot);
        OnRuneEquipped?.Invoke(otherEquip.EquipIndex, swappedIcon);
      }
      else
      {
        // 另一插槽被腾空（移动而非调换）
        otherEquip.Unequip();
        OnRuneUnequipped?.Invoke(otherEquip.EquipIndex);
      }

      // 通知 LobbyCanvas 更新选中插槽图标
      OnRuneEquipped?.Invoke(equipSlot.EquipIndex, newIcon);

      Debug.Log($"[RunePanel] 调换符文: 插槽{equipSlot.EquipIndex}←{newRuneId}, 插槽{otherEquip.EquipIndex}←{swappedRuneId}");
    }
    else
    {
      // 情况3：全新装备 → 直接装备到选中插槽
      equipSlot.Equip(newRuneId, newIcon, runeSlot);
      ApplyEquipEffect(newRuneId);

      // 通知 LobbyCanvas
      OnRuneEquipped?.Invoke(equipSlot.EquipIndex, newIcon);

      Debug.Log($"[RunePanel] 装备符文: 插槽{equipSlot.EquipIndex} ← {runeSlot.RuneName}");
    }

    return true;
  }

  /// <summary>应用装备效果（留空，仅记录装备符文，进入游戏时调用）</summary>
  private void ApplyEquipEffect(int runeId)
  {
    // TODO: 实际游戏效果在进入游戏时根据 EquippedRuneId 应用
  }

  // ──────────────────────────────────────────────
  //  分解重复符文
  // ──────────────────────────────────────────────

  private void OnBreakdownClicked()
  {
    int beforeCount = ownedRuneIds.Count;

    // 1. 去重 DefaultRuneIds（永久生效，分解后不再恢复重复）
    var dedupedDefaults = new List<int>();
    var seenDefaults = new HashSet<int>();
    foreach (int id in DefaultRuneIds)
    {
      if (seenDefaults.Add(id))
        dedupedDefaults.Add(id);
    }
    DefaultRuneIds = dedupedDefaults;

    // 2. 去重 RuneInventory（PlayerPrefs 持久化）
    RuneInventory.BreakdownDuplicates();

    // 3. 重建 ownedRuneIds
    MergeInventoryRunes();

    int removedCount = beforeCount - ownedRuneIds.Count;
    if (removedCount == 0)
    {
      Debug.Log("[RunePanel] 没有可分解的重复符文");
      return;
    }

    // 每个分解的符文返还 30 金币
    int reward = removedCount * 30;
    if (Managers.CoinManager.Instance != null)
      Managers.CoinManager.Instance.AddCoins(reward);

    AudioManager.Instance?.PlayUI("sfx_Coin");

    // 4. 重建符文列表
    BuildRuneSlotList();
    RestoreEquipReferences();
    RefreshAllEquippedMarks();
    ReorderEquippedToFront();

    // 5. 重新选中列表第一项
    DeselectAllItems();
    if (runeSlotList.Count > 0)
      SetRuneSlotItemSelected(runeSlotList[0]);

    Debug.Log($"[RunePanel] 分解完成：移除 {removedCount} 个重复符文，获得 {reward} 金币");

    // 通知 TopNotice 显示分解成功
    var topNotice = FindObjectOfType<UI.Framework.TopNotice>();
    if (topNotice != null)
      topNotice.Show("分解成功");
  }

  // ──────────────────────────────────────────────
  //  已装备标记刷新
  // ──────────────────────────────────────────────

  /// <summary>遍历所有 RuneSlot，刷新已装备标记（按实例精确匹配）</summary>
  private void RefreshAllEquippedMarks()
  {
    foreach (var go in runeSlotList)
    {
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot == null) continue;

      bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneSlot == runeSlot) ||
                        (runeEquip2 != null && runeEquip2.EquippedRuneSlot == runeSlot);
      runeSlot.SetEquipped(isEquipped);
    }
  }

  /// <summary>将已装备的符文插槽移到列表最前面</summary>
  private void ReorderEquippedToFront()
  {
    // 收集已装备的 GameObject
    var equippedGOs = new List<GameObject>();
    var unequippedGOs = new List<GameObject>();
    foreach (var go in runeSlotList)
    {
      if (go == null) continue;
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot == null) continue;

      bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneSlot == runeSlot) ||
                        (runeEquip2 != null && runeEquip2.EquippedRuneSlot == runeSlot);
      if (isEquipped)
        equippedGOs.Add(go);
      else
        unequippedGOs.Add(go);
    }

    // 按顺序设置 hierarchy 层级
    runeSlotList.Clear();
    int siblingIndex = 0;
    foreach (var go in equippedGOs)
    {
      go.transform.SetSiblingIndex(siblingIndex++);
      runeSlotList.Add(go);
    }
    foreach (var go in unequippedGOs)
    {
      go.transform.SetSiblingIndex(siblingIndex++);
      runeSlotList.Add(go);
    }
  }

  // ──────────────────────────────────────────────
  //  外部接口
  // ──────────────────────────────────────────────

  /// <summary>获取当前选中的装备插槽</summary>
  public RuneEquip GetSelectedEquip() => selectedEquip;
  public RuneEquip GetEquip1() => runeEquip1;
  public RuneEquip GetEquip2() => runeEquip2;

  /// <summary>由 LobbyCanvas 调用，选中指定索引的装备插槽 (0/1)</summary>
  public void SelectEquipSlot(int index)
  {
    var target = index == 0 ? runeEquip1 : runeEquip2;
    if (target != null)
      OnEquipSlotSelected(target);
  }

  // ──────────────────────────────────────────────
  //  取消所有选中
  // ──────────────────────────────────────────────

  private void DeselectAllItems()
  {
    selectedRuneListItem = null;
    selectedEquip?.SetSelected(false);
    selectedEquip = null;
  }

  // ──────────────────────────────────────────────
  //  拖拽丢落处理
  // ──────────────────────────────────────────────

  private void OnDestroy()
  {
    // 取消订阅事件，防止内存泄漏
    RuneSlot.OnDragStarted -= OnAnyRuneDragStarted;
    RuneSlot.OnDragEnded -= OnAnyRuneDragEnded;

    if (runeEquip1 != null)
    {
      runeEquip1.OnSelected -= OnEquipSlotSelected;
      runeEquip1.OnDropReceived -= OnRuneDropReceived;
    }
    if (runeEquip2 != null)
    {
      runeEquip2.OnSelected -= OnEquipSlotSelected;
      runeEquip2.OnDropReceived -= OnRuneDropReceived;
    }
  }

  /// <summary>拖拽开始时高亮装备插槽，提示可拖放区域</summary>
  private void OnAnyRuneDragStarted(RuneSlot runeSlot)
  {
    SetEquipSlotsHighlight(true);
  }

  /// <summary>拖拽结束时取消装备插槽高亮</summary>
  private void OnAnyRuneDragEnded(RuneSlot runeSlot)
  {
    SetEquipSlotsHighlight(false);
  }

  /// <summary>符文拖拽丢落到装备插槽上时执行装备</summary>
  private void OnRuneDropReceived(RuneEquip equip, RuneSlot runeSlot)
  {
    if (EquipRune(runeSlot, equip))
    {
      // 装备成功 → 刷新标记并重排
      RefreshAllEquippedMarks();
      ReorderEquippedToFront();

      // 选中该装备插槽（同步 UI 选中状态）
      OnEquipSlotSelected(equip);
    }
  }

  /// <summary>切换装备插槽的高亮状态</summary>
  private void SetEquipSlotsHighlight(bool highlight)
  {
    if (runeEquip1 != null)
      runeEquip1.SetHighlight(highlight, dragTargetHighlightColor);
    if (runeEquip2 != null)
      runeEquip2.SetHighlight(highlight, dragTargetHighlightColor);
  }
}

