using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UnityEngine;
using UnityEngine.UI;

namespace UI
{
  public class RuneInfoPanel : MonoBehaviour
  {
    private Text runeNameText;
    private Text runePowers_1Text;
    private Text runePowers_2Text;
    private Text specialPowerNameText;
    private Text specialPowerDescriptionText;

    void Awake()
    {
      Intilize();
    }

    private void Intilize()
    {
      // 使用安全的组件获取方式
      runeNameText = SafeGetComponent<Text>(transform.Find("RuneName"));
      specialPowerNameText = SafeGetComponent<Text>(
          transform.Find("SpecialPower/SpecialName")
      );
      specialPowerDescriptionText = SafeGetComponent<Text>(
          transform.Find("SpecialPower/SpecialDescription")
      );
      runePowers_1Text = SafeGetComponent<Text>(transform.Find("PowerPanel/PowerInfo_1"));
      runePowers_2Text = SafeGetComponent<Text>(transform.Find("PowerPanel/PowerInfo_2"));
    }

    private T SafeGetComponent<T>(Transform parent)
        where T : Component
    {
      if (parent == null)
      {
        Debug.LogWarning($"[RuneInfoPanel] 找不到父对象");
        return null;
      }

      T component = parent.GetComponent<T>();
      if (component == null)
      {
        Debug.LogWarning($"[RuneInfoPanel] 找不到 {typeof(T).Name} 组件");
      }
      return component;
    }

    private void OnEnable()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.runeInfoChannel.RegisterListener(RuneEventTran);
    }

    private void OnDisable()
    {
      UnregisterEvents();
    }

    private void OnDestroy()
    {
      UnregisterEvents();
    }

    private void UnregisterEvents()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.runeInfoChannel.UnregisterListener(RuneEventTran);
    }

    private void RuneEventTran(RuneEquipArgs runeEquipArgs)
    {
      // 防御性检查：对象可能已销毁
      if (this == null || runeEquipArgs == null)
        return;

      UpdateRuneInfo(
          runeEquipArgs.runeName,
          runeEquipArgs.runePowers,
          runeEquipArgs.specialPowerName,
          runeEquipArgs.specialPowerDescription
      );
    }

    private void UpdateRuneInfo(
        string runeName,
        List<RunePower> runePowers,
        string specialPowerName,
        string specialPowerDescription
    )
    {
      Debug.Log("UpdateRuneInfo");

      if (runeNameText != null)
        runeNameText.text = runeName;

      if (specialPowerNameText != null)
        specialPowerNameText.text = specialPowerName;

      if (specialPowerDescriptionText != null)
        specialPowerDescriptionText.text = specialPowerDescription;

      // 清空两个属性文本，防止上次残留
      if (runePowers_1Text != null)
        runePowers_1Text.text = string.Empty;
      if (runePowers_2Text != null)
        runePowers_2Text.text = string.Empty;

      if (runePowers == null)
        return;

      for (int i = 0; i < runePowers.Count && i < 2; i++)
      {
        var power = runePowers[i];
        string text = power.value > 0
            ? $"+{power.value}{power.label}"
            : $"{power.value}{power.label}";

        if (i == 0 && runePowers_1Text != null)
          runePowers_1Text.text = text;
        else if (i == 1 && runePowers_2Text != null)
          runePowers_2Text.text = text;
      }
    }
  }
}

using System.Collections.Generic;
using Core;
using DG.Tweening;
using UI.Framework.Base;
using UI.Framework.Manager;
using UI.Framework.Panel;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UI.Input;

namespace UI.Framework.Widget
{
    /// <summary>
    /// 大厅符文插槽组件：管理两个符文插槽的选择、图标更新、悬浮动画。
    /// 通过 RunePanel 事件回调更新图标。
    /// </summary>
    public class LobbyRuneSlotWidget : UIWidget
    {
        private const string RunePanelId = "RunePanel";

        [Header("符文插槽")]
        [SerializeField] private Button runeSlot1Button;
        [SerializeField] private Button runeSlot2Button;

        private Transform _runeSlot1Icon;
        private Transform _runeSlot2Icon;
        private GameObject _selectedRuneIcon;

        private Sprite _selectedButtonImage;
        private Sprite _defaultButtonImage;

        protected override void AutoBindComponents()
        {
            if (runeSlot1Button != null)
                _runeSlot1Icon = runeSlot1Button.transform.Find("Icon");
            if (runeSlot2Button != null)
                _runeSlot2Icon = runeSlot2Button.transform.Find("Icon");

            _selectedButtonImage = AssetLoader.LoadAsset<Sprite>("UI/SelectedButton");
            _defaultButtonImage = AssetLoader.LoadAsset<Sprite>("UI/DefaultButton");
        }

        protected override void OnEnable()
        {
            base.OnEnable();
            SubscribeToRunePanel();
        }

        protected override void OnDisable()
        {
            base.OnDisable();
            UnsubscribeFromRunePanel();
        }

        protected override void SubscribeEvents()
        {
            if (runeSlot1Button != null)
            {
                runeSlot1Button.onClick.AddListener(OnRuneSlot1Clicked);
                AddRuneSlotHoverAnimation(runeSlot1Button.gameObject);
            }
            if (runeSlot2Button != null)
            {
                runeSlot2Button.onClick.AddListener(OnRuneSlot2Clicked);
                AddRuneSlotHoverAnimation(runeSlot2Button.gameObject);
            }
        }

        protected override void UnsubscribeEvents()
        {
            if (runeSlot1Button != null)
                runeSlot1Button.onClick.RemoveListener(OnRuneSlot1Clicked);
            if (runeSlot2Button != null)
                runeSlot2Button.onClick.RemoveListener(OnRuneSlot2Clicked);
        }

        protected virtual void Update()
        {
            if (UnityEngine.Input.GetMouseButtonDown(0)
                && _selectedRuneIcon != null
                && CanDeselectRuneIcons()
                && !IsPointerOverRuneSlot())
            {
                DeselectRuneIcons();
            }
        }

        // ──────────────────────────────────────────────
        //  RunePanel 事件对接
        // ──────────────────────────────────────────────

        private void SubscribeToRunePanel()
        {
            var runePanel = UIManager.HasInstance
                ? UIManager.Instance.GetScreen(RunePanelId) as RunePanel
                : null;
            if (runePanel != null)
            {
                runePanel.OnRuneEquipped += OnRuneEquipped;
                runePanel.OnRuneUnequipped += OnRuneUnequipped;
            }
        }

        private void UnsubscribeFromRunePanel()
        {
            if (!UIManager.HasInstance) return;
            var runePanel = UIManager.Instance.GetScreen(RunePanelId) as RunePanel;
            if (runePanel != null)
            {
                runePanel.OnRuneEquipped -= OnRuneEquipped;
                runePanel.OnRuneUnequipped -= OnRuneUnequipped;
            }
        }

        // ──────────────────────────────────────────────
        //  插槽点击
        // ──────────────────────────────────────────────

        private void OnRuneSlot1Clicked()
        {
            CloseOtherPanels();
            SetRuneIconSelected(runeSlot1Button?.gameObject);
            OpenRunePanel();
            NotifyRunePanelSlot(0);
        }

        private void OnRuneSlot2Clicked()
        {
            CloseOtherPanels();
            SetRuneIconSelected(runeSlot2Button?.gameObject);
            OpenRunePanel();
            NotifyRunePanelSlot(1);
        }

        private void CloseOtherPanels()
        {
            ClosePanel("CharactorPanel");
            ClosePanel("ShopPanel");
        }

        private void OpenRunePanel()
        {
            var runePanel = UIManager.Instance.GetScreen(RunePanelId) as RunePanel;
            if (runePanel == null)
            {
                Debug.LogError($"[LobbyRuneSlotWidget] 未找到 {RunePanelId}");
                return;
            }
            if (!runePanel.IsOpen)
                runePanel.Open();
        }

        private void NotifyRunePanelSlot(int slotIndex)
        {
            var runePanel = UIManager.Instance.GetScreen(RunePanelId) as RunePanel;
            if (runePanel != null)
                runePanel.SelectEquipSlot(slotIndex);
        }

        private void ClosePanel(string panelId)
        {
            var panel = UIManager.Instance.GetScreen(panelId);
            if (panel != null)
                panel.Close();
        }

        // ──────────────────────────────────────────────
        //  RunePanel 回调
        // ──────────────────────────────────────────────

        private void OnRuneEquipped(int slotIndex, Sprite equippedSprite)
        {
            Transform targetIcon = slotIndex == 0 ? _runeSlot1Icon : _runeSlot2Icon;
            if (targetIcon != null)
            {
                var img = targetIcon.GetComponent<Image>();
                if (img != null)
                    img.sprite = equippedSprite;
            }
        }

        private void OnRuneUnequipped(int slotIndex)
        {
            Transform targetIcon = slotIndex == 0 ? _runeSlot1Icon : _runeSlot2Icon;
            if (targetIcon != null)
            {
                var img = targetIcon.GetComponent<Image>();
                if (img != null)
                    img.sprite = null;
            }
        }

        // ──────────────────────────────────────────────
        //  插槽选中状态
        // ──────────────────────────────────────────────

        private void SetRuneIconSelected(GameObject icon)
        {
            _selectedRuneIcon = icon;

            if (runeSlot1Button != null)
            {
                runeSlot1Button.GetComponent<Image>().sprite =
                    icon == runeSlot1Button.gameObject ? _selectedButtonImage : _defaultButtonImage;
                runeSlot1Button.transform.DOScale(icon == runeSlot1Button.gameObject ? 1.1f : 1f, 0.2f);
            }

            if (runeSlot2Button != null)
            {
                runeSlot2Button.GetComponent<Image>().sprite =
                    icon == runeSlot2Button.gameObject ? _selectedButtonImage : _defaultButtonImage;
                runeSlot2Button.transform.DOScale(icon == runeSlot2Button.gameObject ? 1.1f : 1f, 0.2f);
            }
        }

        private void DeselectRuneIcons()
        {
            if (_selectedRuneIcon == null) return;
            _selectedRuneIcon = null;

            if (runeSlot1Button != null)
            {
                runeSlot1Button.GetComponent<Image>().sprite = _defaultButtonImage;
                runeSlot1Button.transform.DOScale(1f, 0.2f);
            }

            if (runeSlot2Button != null)
            {
                runeSlot2Button.GetComponent<Image>().sprite = _defaultButtonImage;
                runeSlot2Button.transform.DOScale(1f, 0.2f);
            }
        }

        private bool CanDeselectRuneIcons()
        {
            if (!UIManager.HasInstance) return false;
            var runePanel = UIManager.Instance.GetScreen(RunePanelId);
            return runePanel == null || (!runePanel.IsOpen && !runePanel.IsAnimating);
        }

        private bool IsPointerOverRuneSlot()
        {
            if (EventSystem.current == null) return false;

            var pointerData = new PointerEventData(EventSystem.current)
            {
                position = MobileInputHelper.GetScreenPosition(),
            };

            var results = new List<RaycastResult>();
            EventSystem.current.RaycastAll(pointerData, results);

            foreach (var result in results)
            {
                GameObject go = result.gameObject;
                if (go == runeSlot1Button?.gameObject
                    || go == runeSlot2Button?.gameObject
                    || (runeSlot1Button != null && go.transform.IsChildOf(runeSlot1Button.transform))
                    || (runeSlot2Button != null && go.transform.IsChildOf(runeSlot2Button.transform)))
                {
                    return true;
                }
            }
            return false;
        }

        // ──────────────────────────────────────────────
        //  悬浮动画
        // ──────────────────────────────────────────────

        private void AddRuneSlotHoverAnimation(GameObject slot)
        {
            var trigger = slot.GetComponent<EventTrigger>();
            if (trigger == null)
                trigger = slot.AddComponent<EventTrigger>();

            var enter = new EventTrigger.Entry { eventID = EventTriggerType.PointerEnter };
            enter.callback.AddListener(_ => slot.transform.DOScale(1.1f, 0.2f));
            trigger.triggers.Add(enter);

            var exit = new EventTrigger.Entry { eventID = EventTriggerType.PointerExit };
            exit.callback.AddListener(_ =>
            {
                if (_selectedRuneIcon != slot)
                    slot.transform.DOScale(1f, 0.2f);
            });
            trigger.triggers.Add(exit);
        }
    }
}

using Controllers.Rune;
using UI.Framework;
using UnityEngine;
using UnityEngine.UI;

public class ShopRuneSlot : MonoBehaviour
{
  [Header("价格显示")]
  [SerializeField] private Text priceText;
  [SerializeField] private Text stockText;

  private RuneSlot runeSlot;
  private ShopRuneConfigSO shopRuneConfig;
  private System.Action<ShopRuneConfigSO, RuneSlot> onSelected;

  public void Initialize(RuneSlot slot, ShopRuneConfigSO config, System.Action<ShopRuneConfigSO, RuneSlot> selectedCallback)
  {
    runeSlot = slot;
    shopRuneConfig = config;
    onSelected = selectedCallback;

    if (runeSlot != null)
    {
      runeSlot.Setup(config.runeData);
      runeSlot.OnClicked += OnSlotClicked;
    }

    UpdatePriceAndStock();
  }

  private void OnSlotClicked(RuneSlot slot)
  {
    onSelected?.Invoke(shopRuneConfig, runeSlot);
  }

  public void Deselect()
  {
    if (runeSlot != null && runeSlot.IsSelected)
      runeSlot.PlayDeselect();
  }

  public void UpdatePriceAndStock()
  {
    if (priceText != null && shopRuneConfig != null)
    {
      priceText.text = $"{shopRuneConfig.price} 金币";
    }

    if (stockText != null && shopRuneConfig != null)
    {
      if (shopRuneConfig.isLimitedStock)
      {
        int remaining = Managers.ShopManager.Instance.GetRemainingStock(shopRuneConfig.runeId);
        stockText.text = remaining > 0 ? $"库存: {remaining}" : "已售罄";
        stockText.gameObject.SetActive(true);
      }
      else
      {
        stockText.gameObject.SetActive(false);
      }
    }

    var image = GetComponent<Image>();
    if (image == null) return;

    bool isPurchased = shopRuneConfig != null
        && !shopRuneConfig.allowRepeatPurchase
        && RuneInventory.HasRune(shopRuneConfig.runeId);
    float alpha = image.color.a;
    image.color = isPurchased
        ? new Color(0.5f, 0.5f, 0.5f, alpha)
        : new Color(1f, 1f, 1f, alpha);
  }

  void OnDestroy()
  {
    if (runeSlot != null)
    {
      runeSlot.OnClicked -= OnSlotClicked;
    }
  }
}

using System.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

namespace Core
{
    /// <summary>
    /// 统一资产加载适配层，封装 Addressables 调用。
    /// 提供同步/异步两种接口，替代 Resources.Load。
    /// </summary>
    public static class AssetLoader
    {
        // ========== 异步加载（推荐） ==========

        /// <summary>异步加载资产</summary>
        public static async Task<T> LoadAssetAsync<T>(string key) where T : Object
        {
            var handle = Addressables.LoadAssetAsync<T>(key);
            await handle.Task;
            if (handle.Status == AsyncOperationStatus.Succeeded)
                return handle.Result;
            Debug.LogError($"[AssetLoader] 加载失败: {key}");
            return null;
        }

        /// <summary>异步实例化 Prefab</summary>
        public static async Task<GameObject> InstantiateAsync(string key, Vector3 pos = default, Quaternion rot = default)
        {
            var handle = Addressables.InstantiateAsync(key, pos, rot);
            await handle.Task;
            if (handle.Status == AsyncOperationStatus.Succeeded)
                return handle.Result;
            Debug.LogError($"[AssetLoader] 实例化失败: {key}");
            return null;
        }

        // ========== 同步加载（兼容现有代码） ==========

        /// <summary>同步加载资产（阻塞，仅初始化阶段使用）</summary>
        public static T LoadAsset<T>(string key) where T : Object
        {
            var handle = Addressables.LoadAssetAsync<T>(key);
            handle.WaitForCompletion();
            if (handle.Status == AsyncOperationStatus.Succeeded)
                return handle.Result;
            Debug.LogError($"[AssetLoader] 加载失败: {key}");
            return null;
        }

        /// <summary>同步尝试加载资产（不打印错误日志，用于 fallback 探测）</summary>
        public static T TryLoadAsset<T>(string key) where T : Object
        {
            if (!KeyExists(key, typeof(T)))
                return null;

            try
            {
                var handle = Addressables.LoadAssetAsync<T>(key);
                handle.WaitForCompletion();
                if (handle.Status == AsyncOperationStatus.Succeeded)
                    return handle.Result;
                Addressables.Release(handle);
                return null;
            }
            catch
            {
                return null;
            }
        }

        /// <summary>检查 Addressable key 是否存在（不抛异常、不打日志）</summary>
        public static bool KeyExists(string key, System.Type type = null)
        {
            if (string.IsNullOrEmpty(key)) return false;
            try
            {
                var handle = type != null
                    ? Addressables.LoadResourceLocationsAsync(key, type)
                    : Addressables.LoadResourceLocationsAsync(key);
                handle.WaitForCompletion();
                bool exists = handle.Status == AsyncOperationStatus.Succeeded
                              && handle.Result != null
                              && handle.Result.Count > 0;
                Addressables.Release(handle);
                return exists;
            }
            catch
            {
                return false;
            }
        }

        /// <summary>同步实例化 Prefab（阻塞，仅初始化阶段使用）</summary>
        public static GameObject Instantiate(string key, Vector3 pos = default, Quaternion rot = default)
        {
            var handle = Addressables.InstantiateAsync(key, pos, rot);
            handle.WaitForCompletion();
            if (handle.Status == AsyncOperationStatus.Succeeded)
                return handle.Result;
            Debug.LogError($"[AssetLoader] 实例化失败: {key}");
            return null;
        }

        // ========== 释放 ==========

        /// <summary>释放资产引用</summary>
        public static void Release<T>(T asset) where T : Object
        {
            if (asset != null)
                Addressables.Release(asset);
        }

        /// <summary>释放通过 InstantiateAsync 实例化的对象</summary>
        public static void ReleaseInstance(GameObject instance)
        {
            if (instance != null)
                Addressables.ReleaseInstance(instance);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

namespace Core
{
    /// <summary>
    /// Addressables 热更新管理器。
    /// 游戏启动时检查远程 catalog 是否有更新，有则下载变化的 bundle。
    /// 需挂在启动场景的 GameObject 上，且应在 GameManager/LuaEnvManager 之前执行。
    /// </summary>
    public class AddressablesUpdater : MonoBehaviour
    {
        public enum UpdateState { Idle, Checking, Downloading, Complete, Failed }

        public static AddressablesUpdater Instance { get; private set; }

        /// <summary>热更新是否已完成</summary>
        public static bool IsUpdateComplete { get; private set; }

        /// <summary>热更下载进度 (0~1)</summary>
        public static float DownloadProgress { get; private set; }

        /// <summary>是否检测到了远程更新</summary>
        public static bool HasRemoteUpdate { get; private set; }

        /// <summary>当前热更状态</summary>
        public static UpdateState State { get; private set; }

        /// <summary>需要下载的总字节数</summary>
        public static long TotalDownloadBytes { get; private set; }

        /// <summary>下载开始的时间（用于 UI 保证最小显示时长）</summary>
        public static float DownloadStartTime { get; private set; }

        [Header("热更配置")]
        [Tooltip("需要预下载的资源 Label（用逗号分隔的 Label 列表，不是 Group 名）")]
        [SerializeField] private List<string> preloadLabels = new List<string>
        {
            "remote_preload"
        };

        [Tooltip("开发模式：跳过远程检查，仅使用本地 catalog（Editor 测试用）")]
        [SerializeField] private bool devMode = false;

        private void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
                DontDestroyOnLoad(gameObject);
            }
            else
            {
                Destroy(gameObject);
            }
        }

        private IEnumerator Start()
        {
            IsUpdateComplete = false;
            DownloadProgress = 0f;
            HasRemoteUpdate = false;
            State = UpdateState.Idle;
            TotalDownloadBytes = 0;

            // 开发模式：跳过远程检查
            if (devMode)
            {
                Debug.Log("[热更] 开发模式：初始化 Addressables...");
                var devInitHandle = Addressables.InitializeAsync();
                yield return devInitHandle;
                Debug.Log("[热更] 开发模式：跳过远程检查，使用本地 catalog");
                State = UpdateState.Complete;
                IsUpdateComplete = true;
                DownloadProgress = 1f;
                yield break;
            }

            // 1. 读取玩家包内置 catalog，计算其 MD5 hash
            State = UpdateState.Checking;
            DownloadStartTime = Time.time;
            Debug.Log("[热更] 检查 catalog 更新...");

            string builtinHash = ComputeBuiltinCatalogHash();
            Debug.Log($"[热更] 内置 catalog hash: {builtinHash}");

            // 2. 下载远程 hash
            string remoteHash = null;
            var remoteHashPath = "https://a.unity.cn/client_api/v1/buckets/9a90add4-6c36-4796-a3ea-9114ea7561dc/release_by_badge/latest/content/catalog_0.1.hash";
            using (var www = UnityEngine.Networking.UnityWebRequest.Get(remoteHashPath))
            {
                www.redirectLimit = 10;
                yield return www.SendWebRequest();
                if (www.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    remoteHash = www.downloadHandler.text.Trim();
                    Debug.Log($"[热更] 远程 catalog hash: {remoteHash}");
                }
                else
                {
                    Debug.LogError($"[热更] 获取远程 hash 失败: {www.error}");
                }
            }

            // 3. 对比：远程 hash ≠ 内置 hash → 需要更新
            bool needUpdate = false;
            if (!string.IsNullOrEmpty(remoteHash) && !string.IsNullOrEmpty(builtinHash) && remoteHash != builtinHash)
            {
                needUpdate = true;
                HasRemoteUpdate = true;
                Debug.Log("[热更] 检测到 catalog 需要更新（远程 hash ≠ 内置 hash）");
            }
            else if (string.IsNullOrEmpty(remoteHash))
            {
                Debug.LogWarning("[热更] 无法获取远程 hash，跳过更新");
            }
            else
            {
                Debug.Log("[热更] Catalog 无需更新（远程 hash = 内置 hash）");
            }

            // 4. 初始化 Addressables
            Debug.Log("[热更] 初始化 Addressables...");
            var initHandle = Addressables.InitializeAsync();
            yield return initHandle;

            if (needUpdate)
            {
                // 手动下载远程 catalog 写入缓存，再重新初始化
                Debug.Log("[热更] 正在下载远程 catalog...");
                yield return DownloadRemoteCatalog(remoteHashPath);
            }

            // 打印 catalog 中的资源信息，用于调试
            Debug.Log("[热更] === 当前内存中的 Catalog 资源列表 ===");
            foreach (var locator in UnityEngine.AddressableAssets.Addressables.ResourceLocators)
            {
                Debug.Log($"[热更] Locator: {locator.LocatorId}");
                long count = 0;
                foreach (var key in locator.Keys)
                {
                    var keyStr = key.ToString();
                    if (keyStr.Contains("rune", System.StringComparison.OrdinalIgnoreCase) ||
                        keyStr.Contains("shop", System.StringComparison.OrdinalIgnoreCase) ||
                        keyStr.Contains("RuneExplosion", System.StringComparison.OrdinalIgnoreCase) ||
                        keyStr.Contains("RuneTripleBoost", System.StringComparison.OrdinalIgnoreCase))
                    {
                        if (locator.Locate(key, typeof(UnityEngine.Object), out var locations))
                        {
                            foreach (var loc in locations)
                            {
                                Debug.Log($"[热更]   {keyStr} → {loc.InternalId}");
                            }
                        }
                    }
                    count++;
                }
                Debug.Log($"[热更] Locator 总资源数: {count}");
            }
            Debug.Log("[热更] === Catalog 资源列表结束 ===");

            if (!needUpdate)
            {
                State = UpdateState.Complete;
                IsUpdateComplete = true;
                DownloadProgress = 1f;
                Debug.Log("[热更] 已是最新版本，跳过下载");
                yield break;
            }

            // 5. 计算需要下载的大小（通过 Label 预下载）
            Debug.Log("[热更] 计算下载大小...");
            var sizeHandle = Addressables.GetDownloadSizeAsync(preloadLabels.AsReadOnly());
            yield return sizeHandle;

            TotalDownloadBytes = sizeHandle.Result;
            Addressables.Release(sizeHandle);

            if (TotalDownloadBytes <= 0)
            {
                State = UpdateState.Complete;
                IsUpdateComplete = true;
                DownloadProgress = 1f;
                Debug.Log("[热更] 无需下载新资源");
                yield break;
            }

            float totalMB = TotalDownloadBytes / 1024f / 1024f;
            Debug.Log($"[热更] 需要下载 {totalMB:F1} MB");

            // 6. 下载更新的 bundle
            State = UpdateState.Downloading;
            var downloadHandle = Addressables.DownloadDependenciesAsync(
                preloadLabels.AsReadOnly(),
                Addressables.MergeMode.Union
            );

            while (!downloadHandle.IsDone)
            {
                DownloadProgress = downloadHandle.PercentComplete;
                yield return null;
            }

            if (downloadHandle.Status == AsyncOperationStatus.Succeeded)
            {
                DownloadProgress = 1f;
                State = UpdateState.Complete;
                IsUpdateComplete = true;
                Debug.Log("[热更] 资源下载完成");
            }
            else
            {
                State = UpdateState.Failed;
                Debug.LogError("[热更] 下载失败，使用本地缓存继续");
                IsUpdateComplete = true;
            }

            Addressables.Release(downloadHandle);
        }

        /// <summary>
        /// 手动下载远程 catalog 并写入缓存，绕过 CheckForCatalogUpdates 的缓存机制
        /// </summary>
        private IEnumerator DownloadRemoteCatalog(string hashUrl)
        {
            // 远程 catalog URL = 把 hash 文件 URL 中的 .hash 替换为 .json
            string catalogUrl = hashUrl.Replace(".hash", ".json");

            Debug.Log($"[热更] 下载远程 catalog: {catalogUrl}");
            using (var www = UnityEngine.Networking.UnityWebRequest.Get(catalogUrl))
            {
                www.redirectLimit = 10;
                yield return www.SendWebRequest();

                if (www.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    string catalogJson = www.downloadHandler.text;

                    // 写入缓存目录
                    string cacheDir = System.IO.Path.Combine(UnityEngine.Application.persistentDataPath, "com.unity.addressables");
                    System.IO.Directory.CreateDirectory(cacheDir);

                    System.IO.File.WriteAllText(
                        System.IO.Path.Combine(cacheDir, "catalog_0.1.json"),
                        catalogJson);

                    // 下载并写入 hash 文件
                    using (var hashReq = UnityEngine.Networking.UnityWebRequest.Get(hashUrl))
                    {
                        hashReq.redirectLimit = 10;
                        yield return hashReq.SendWebRequest();
                        if (hashReq.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(cacheDir, "catalog_0.1.hash"),
                                hashReq.downloadHandler.text);
                        }
                    }

                    Debug.Log("[热更] 远程 catalog 已下载并写入缓存，正在重新初始化...");

                    // 重新初始化 Addressables 加载新 catalog
                    var reinitHandle = Addressables.InitializeAsync();
                    yield return reinitHandle;
                    Debug.Log("[热更] 重新初始化完成，新 catalog 已加载");
                }
                else
                {
                    Debug.LogError($"[热更] 下载远程 catalog 失败: {www.error}");
                }
            }
        }

        /// <summary>
        /// 计算玩家包内置 catalog 的 MD5 hash
        /// catalog_0.1.hash 文件的内容就是 catalog_0.1.json 内容的 MD5
        /// </summary>
        private string ComputeBuiltinCatalogHash()
        {
            try
            {
                // 内置 catalog 路径：StreamingAssets/aa/catalog.json
                string catalogPath = System.IO.Path.Combine(
                    UnityEngine.Application.streamingAssetsPath, "aa", "catalog.json");

                if (!System.IO.File.Exists(catalogPath))
                {
                    Debug.LogWarning($"[热更] 内置 catalog 不存在: {catalogPath}");
                    return null;
                }

                string catalogContent = System.IO.File.ReadAllText(catalogPath);
                using (var md5 = System.Security.Cryptography.MD5.Create())
                {
                    byte[] bytes = System.Text.Encoding.UTF8.GetBytes(catalogContent);
                    byte[] hash = md5.ComputeHash(bytes);
                    return System.BitConverter.ToString(hash).Replace("-", "").ToLower();
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[热更] 计算内置 catalog hash 失败: {ex.Message}");
                return null;
            }
        }
    }
